+		return nil, reject("service_request.complete_repair.usage_lines_invalid")
+	}
+	if len(lines) == 0 {
+		return nil, reject("service_request.complete_repair.usage_lines_required")
+	}
+	seen := make(map[string]struct{}, len(lines))
+	for _, line := range lines {
+		if line.SparePartID == "" || line.Quantity <= 0 {
+			return nil, reject("service_request.complete_repair.usage_line_invalid")
+		}
+		if _, exists := seen[line.SparePartID]; exists {
+			return nil, reject("service_request.complete_repair.duplicate_spare_part")
+		}
+		seen[line.SparePartID] = struct{}{}
+	}
+	return lines, nil
 }
